local config = {
  ui_story_31880401_1_dialog_content = "<color=#e8d9bb>Un poema dice...</color>",
  ui_story_31880401_2_dialog_content = "<color=#e8d9bb>\"El Rey de Ji, un reino vasallo del Imperio Zhao, ordenó a la Princesa Zhuohua viajar como enviada a las tierras occidentales.\"</color>",
  ui_story_31880401_3_dialog_content = "<color=#e8d9bb>\"Valientemente, ella se aventuró a través de montañas y océanos, incluso en medio de enfrentamientos fronterizos, mostrando un valor inquebrantable ante las adversidades.\"</color>",
  ui_story_31880401_4_dialog_content = "<color=#e8d9bb>\"Mientras deambulaba por un vasto desierto, la soledad y la desesperación crecían en su corazón. Bajo un cielo frío y despejado, sus emociones se volvieron complicadas e intensas.\"</color>",
  ui_story_31880401_5_dialog_content = "<color=#e8d9bb>\"Para aumentar sus penas, un grupo de gansos graznó en dirección a Twin Pavilions Bay, y ella se sintió abrumada por su aislamiento y nostalgia.\"</color>",
  ui_story_31880401_6_dialog_content = "<color=#e8d9bb>A pesar de sus innumerables pruebas y tribulaciones, la Princesa Zhuohua finalmente llegó a las tierras occidentales, y así hizo una breve pausa en Twin Pavilions Bay.</color>",
  ui_story_31880401_7_dialog_content = "<color=#e8d9bb>Como su nombre indica, Twin Pavilions Bay es una ciudad dividida en dos, con una mitad gobernada por Umbraton y la otra por el Gremio Lin.</color>",
  ui_story_31880401_8_dialog_content = "<color=#e8d9bb>En la mitad de la ciudad del gremio Lin, las calles y edificios no se ven diferentes a los de la gran ciudad del Zhao Imperio. A veces confunde a las personas, sin saber dónde están.</color>",
  ui_story_31880401_9_dialog_content = "<color=#e8d9bb>El Caballo Dragón Bai, Jiu Wukong, Meow Bajie y Zen Wujing contemplaron asombrados la mitad de la ciudad de Umbraton, con sus corazones llenos de ambición.</color>",
  ui_story_31880401_10_dialog_content = "<color=#e8d9bb>Sin embargo, la Princesa Zhuohua miraba fijamente un espejo, con la mente aparentemente ocupada por algo preocupante...</color>",
  ui_story_31880401_11_dialog_content = "<color=#e8d9bb>El hermoso rostro reflejado en el espejo me recuerda otro poema...</color>",
  ui_story_31880401_12_dialog_content = "<color=#e8d9bb>\"Piel blanca como el hielo y rasgos tan finos como el jade tallado. Sus mejillas rosadas y labios rojo brillante llenan este mundo de color y belleza.\"</color>",
  ui_story_31880401_13_dialog_content = "<color=#e8d9bb>\"Avanza suavemente, tan ligera y elegante como una brisa entre las ramas de un sauce. Sus ojos evocan la ternura de los pétalos de flores cayendo delicadamente sobre un estanque de agua.\"</color>",
  ui_story_31880401_14_dialog_content = "Wukong, ¿cuánto tiempo ha pasado desde que enviamos una carta al Rey León de Obsidiana solicitando una audiencia?",
  ui_story_31880401_15_dialog_content = "Quince días, si incluimos hoy.",
  ui_story_31880401_16_dialog_content = "Parece que el Rey León de Obsidiana está demasiado ocupado para responder a nosotros.",
  ui_story_31880401_17_dialog_content = "¡No es bueno! ¡No es bueno!",
  ui_story_31880401_18_dialog_content = "¿Por qué estás tan asustado, Bajie?",
  ui_story_31880401_19_dialog_content = "Fui a revisar la casa del Rey León de Obsidiana y encontré nuestra carta en la basura. ¡La tiraron!",
  ui_story_31880401_20_dialog_content = "¿Qué?",
  ui_story_31880401_21_dialog_content = "¡Wujing también lo vio! ¡Pregúntale si no me crees!",
  ui_story_31880401_22_dialog_content = "Está diciendo la verdad, Su Alteza. Yo también lo vi.",
  ui_story_31880401_23_dialog_content = "... No es de extrañar que aún no hayamos recibido una respuesta.",
  ui_story_31880401_24_dialog_content = "Parece que apenas somos dignos de la atención del Rey León de Obsidiana.",
  ui_story_31880401_25_dialog_content = "Umbraton no es el único lugar aquí en Astra. Si continuamos viajando hacia el oeste, podemos visitar Illumina o incluso Eraveil.",
  ui_story_31880401_26_dialog_content = "¡Acordado! Si no nos dan ni un momento de su tiempo, ¡nosotros tampoco deberíamos!",
  ui_story_31880401_27_dialog_content = "Este Rey León apenas parece un rey de todos modos. ¡En lo que a mí respecta, es solo otro león sin cerebro!",
  ui_story_31880401_28_dialog_content = "¿Qué dice, Su Alteza? ¿Debo ir y enseñarles una lección?",
  ui_story_31880401_29_dialog_content = "Absolutamente no.",
  ui_story_31880401_30_dialog_content = "No estamos aquí para causar problemas. Recuerda mantener nuestro objetivo final en mente.",
  ui_story_31880401_31_dialog_content = "Siempre es \"meta definitiva\" esto y \"meta definitiva\" aquello. ¿Cómo se supone que lo tenga en mente si ni siquiera me permiten salir, excepto para revisar a ese león?",
  ui_story_31880401_32_dialog_content = "Suficiente, Bajie.",
  ui_story_31880401_33_dialog_content = "Durante los últimos días, me preocupaba que perdiéramos la oportunidad de conocer al Rey León de Obsidiana si nos paseábamos demasiado.",
  ui_story_31880401_34_dialog_content = "Pero parece que ya no necesitamos preocuparnos por eso.",
  ui_story_31880401_35_dialog_content = "Aquí, Wukong. Toma la plata, junto con Bajie y Wujing, y diviértanse.",
  ui_story_31880401_36_dialog_content = "Pero ¿y usted, Su Alteza?",
  ui_story_31880401_37_dialog_content = "Creo que me quedaré aquí y descansaré un rato. Ustedes tres sigan adelante.",
  ui_story_31880401_38_dialog_content = "Descanse mucho entonces, ¡Su Alteza! ¡Le traeremos algunas frutas confitadas más tarde!",
  ui_story_31880401_39_dialog_content = "¡Su Alteza! ¿Ya está despierto?",
  ui_story_31880401_40_dialog_content = "¡Estas frutas confitadas saben igual que las de casa! ¡Aquí, prueba algunas!",
  ui_story_31880401_41_dialog_content = "¿Eh? ¿D-Dónde está Su Alteza?!",
  ui_story_31880401_42_dialog_content = "¿Ella no nos dejó atrás para ir a divertirse sola, verdad?!",
  ui_story_31880401_43_dialog_content = "No, su chal todavía está aquí, lo que significa que Su Alteza probablemente no se fue por su propia voluntad. Si acaso...",
  ui_story_31880401_44_dialog_content = "¿Si algo...?",
  ui_story_31880401_45_dialog_content = "Parece un secuestro.",
  ui_story_31880401_46_dialog_content = "¡¿Qué?!",
  ui_story_31880401_47_dialog_content = "¡Pero no hemos molestado a nadie aquí! ¿Por qué secuestrarían a Su Alteza?",
  ui_story_31880401_48_dialog_content = "Aparte de nosotros, solo hay una persona que sabe que Su Alteza está aquí en este momento.",
  ui_story_31880401_49_dialog_content = "¿El Rey León de Obsidiana?",
  ui_story_31880401_50_dialog_content = "Me transformaré en un insecto e iré a investigar. Ustedes dos quédense aquí y mantengan la cabeza baja.",
  ui_story_31880401_51_dialog_content = "<color=#e8d9bb>¡Maricón!</color>",
  ui_story_31880401_52_dialog_content = "¿Quién iba a saber que este tipo tenía una habitación oculta en su casa así?",
  ui_story_31880401_53_dialog_content = "¿Mmm? ¡Hay alguien adelante!",
  ui_story_31880401_54_dialog_content = "¡Suéltame!",
  ui_story_31880401_55_dialog_content = "¡Jajaja! ¿No crees que tus esfuerzos son en vano ahora?",
  ui_story_31880401_56_dialog_content = "Tú... ¿Qué estás tramando exactamente?",
  ui_story_31880401_57_dialog_content = "Podría hacerte exactamente la misma pregunta. Dime, ¿por qué has venido a Astra?",
  ui_story_31880401_58_dialog_content = "Lo dejé muy claro en la carta. Estamos aquí en una misión de intercambio cultural...",
  ui_story_31880401_59_dialog_content = "¿Un \"intercambio cultural\"? Qué forma tan agradable de expresarlo.",
  ui_story_31880401_60_dialog_content = "Ya puedes dejar el acto. Sabemos que estás trabajando como espía para el este.",
  ui_story_31880401_61_dialog_content = "Aunque afirmas buscar un intercambio cultural, lo que realmente buscas son los secretos mejor guardados de Astra.",
  ui_story_31880401_62_dialog_content = "¡Estás equivocado!",
  ui_story_31880401_63_dialog_content = "Entonces dime, ¿qué pasaría si lográramos establecer un acuerdo comercial exitosamente?",
  ui_story_31880401_64_dialog_content = "Tanto el este como el oeste se beneficiarían enormemente de ello. La maquinaria occidental aparecería en el este y la ingeniosidad oriental llegaría aquí.",
  ui_story_31880401_65_dialog_content = "Qué equivocado estás.",
  ui_story_31880401_66_dialog_content = "Cuando llegue el momento, tu gente bajará los precios de tus productos e inundará todo Astra con ellos.",
  ui_story_31880401_67_dialog_content = "Una vez que nuestros mercados internos estén debilitados y nuestra gente no tenga forma de ganarse la vida...",
  ui_story_31880401_68_dialog_content = "¡Tu emperador enviará sus fuerzas para atacar y conquistar todo Astra!",
  ui_story_31880401_69_dialog_content = "¡Eso es absurdo!",
  ui_story_31880401_70_dialog_content = "No viajé miles de millas hasta Astra solo para crear aún más conflicto entre nuestras culturas...",
  ui_story_31880401_71_dialog_content = "¿Oh? ¿Todavía lo niegas?",
  ui_story_31880401_72_dialog_content = "Entonces, déjame hacerte una última pregunta.",
  ui_story_31880401_73_dialog_content = "Mis fuentes me dicen que quien tome el poder en tu cuerpo puede convertirse en el Aurorian más poderoso que existe. ¿Es eso cierto?",
  ui_story_31880401_74_dialog_content = "¿Q-Qué planeas hacerme?!",
  ui_story_31880401_75_dialog_content = "Oh, mírate, parece ser la verdad.",
  ui_story_31880401_76_dialog_content = "...!!!",
  ui_story_31880401_77_dialog_content = "¡Zumbido, zumbido, zumbido!",
  ui_story_31880401_78_dialog_content = "¿De dónde salió este bicho?",
  ui_story_31880401_79_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_31880401_80_dialog_content = "¡¿Qué dijiste?!",
  ui_story_31880401_81_dialog_content = "¿Así que ese monstruo quiere robar el poder de Su Alteza?",
  ui_story_31880401_82_dialog_content = "¿Por qué no pensé en esa posibilidad...?",
  ui_story_31880401_83_dialog_content = "Oye, espera un minuto. Si Su Alteza no está presente, ¿eso no significa que puedo ir a donde quiera?",
  ui_story_31880401_84_dialog_content = "...",
  ui_story_31880401_85_dialog_content = "¡Oye, oye! Su Alteza dijo que no puedes pegarme.",
  ui_story_31880401_86_dialog_content = "No iba a hacerlo. Ahora escucha atentamente, cada uno de nosotros tiene un trabajo que hacer ahora...",
  ui_story_31880401_87_dialog_content = "¡Sal, monstruo león! ¡Sé que estás ahí dentro!",
  ui_story_31880401_88_dialog_content = "Si tienes el valor de secuestrar a nuestra princesa, ¡también deberías tener el valor de admitirlo!",
  ui_story_31880401_89_dialog_content = "¿Cómo te atreves a ladrar en mi puerta como un perro callejero?",
  ui_story_31880401_90_dialog_content = "É-Él salió... Ahora depende de ti, Wujing!",
  ui_story_31880401_91_dialog_content = "Sí, sí, lo sé.",
  ui_story_31880401_92_dialog_content = "¡Prepárate, Rey León de Obsidiana! Ahora que has secuestrado a nuestra princesa, ¡no tengo razón para contenerme!",
  ui_story_31880401_93_dialog_content = "¡Toma esto!",
  ui_story_31880401_94_dialog_content = "Hmph, trucos tan insignificantes.",
  ui_story_31880401_95_dialog_content = "Urgh...",
  ui_story_31880401_96_dialog_content = "É-Él es demasiado fuerte! Deberíamos correr—",
  ui_story_31880401_97_dialog_content = "¿Te vas tan pronto? ¿Olvidaste dónde estás ahora mismo?",
  ui_story_31880401_98_dialog_content = "¡No escaparás tan fácilmente!",
  ui_story_31880401_99_dialog_content = "...",
  ui_story_31880401_100_dialog_content = "Espera, ¿están... tratando de atraerme lejos?",
  ui_story_31880401_101_dialog_content = "Urgh... ¿Qué...",
  ui_story_31880401_102_dialog_content = "Hmph, no te molestes en buscar. La princesa está sana y salva ahora.",
  ui_story_31880401_103_dialog_content = "Ahora sí podemos divertirnos de verdad.",
  ui_story_31880401_104_dialog_content = "¡Toma esto!",
  ui_story_31880401_105_dialog_content = "¡Espera!",
  ui_story_31880401_106_dialog_content = "¿Dragón Caballo Bai? ¿No se supone que debes estar vigilando nuestro equipo?",
  ui_story_31880401_107_dialog_content = "Encontré a la hija del Rey León de Obsidiana: la Hada Campana.",
  ui_story_31880401_108_dialog_content = "Todos, por favor bajen sus armas.",
  ui_story_31880401_109_dialog_content = "Maestría...",
  ui_story_31880401_110_dialog_content = "\"¿Maestro\"? Eso es nuevo. ¿Por qué tu padre te llamaría así?",
  ui_story_31880401_111_dialog_content = "Ver por ti mismo.",
  ui_story_31880401_112_dialog_content = "<color=#e8d9bb>¡Maricón!</color>",
  ui_story_31880401_113_dialog_content = "...",
  ui_story_31880401_114_dialog_content = "Qué es esto...?",
  ui_story_31880401_115_dialog_content = "Este es Frankel, mi espectro.",
  ui_story_31880401_116_dialog_content = "Parece que Frankel asumió la apariencia de mi padre mientras estábamos fuera y les causó no pocos problemas.",
  ui_story_31880401_117_dialog_content = "¿Oh? ¿Así que el que me llamó perro callejero no fue otro que la mascota de la familia, eh?",
  ui_story_31880401_118_dialog_content = "Bu ju...",
  ui_story_31880401_119_dialog_content = "Cuida tu lengua, Bajie.",
  ui_story_31880401_120_dialog_content = "¡Hmph! ¿Cómo puede seguir siendo tan cortés con ellos, Su Alteza? ¿Ya olvidó lo que le pasó?",
  ui_story_31880401_121_dialog_content = "Fue mi culpa por no entrenar a Frankel lo suficientemente bien.",
  ui_story_31880401_122_dialog_content = "¡Por favor, acepta mis más sinceras disculpas!",
  ui_story_31880401_123_dialog_content = "Me aseguraré de vigilar más de cerca a Frankel, para que esto nunca vuelva a suceder.",
  ui_story_31880401_124_dialog_content = "Como disculpa, permíteme cubrir tus gastos de viaje mientras continúas hacia el oeste.",
  ui_story_31880401_125_dialog_content = "Y si lo desea... también puedo acompañarla a ver a mi padre, princesa.",
  ui_story_31880401_126_dialog_content = "Eso sería muy apreciado.",
  ui_story_31880401_127_dialog_content = "Poco después, la Princesa Zhuohua finalmente consiguió una audiencia con el Rey León Obsidiana, el gobernante de Umbraton.</color>",
  ui_story_31880401_128_dialog_content = "<color=#e8d9bb>Pero, ¿será ella realmente capaz de cumplir con su misión de intercambio cultural?",
  ui_story_31880401_129_dialog_content = "<color=#e8d9bb>¡Lee el siguiente capítulo para descubrirlo!</color>",
  ui_story_31880401_130_dialog_content = "Vaya, este libro parece...",
  ui_story_31880401_131_option_content = "Difícil de entender.",
  ui_story_31880401_132_dialog_content = "¿Las novelas del este realmente tienen que ser tan difíciles de leer?",
  ui_story_31880401_133_dialog_content = "Jeje, llamamos a esos \"poemas de siete caracteres.\"",
  ui_story_31880401_134_dialog_content = "Los literatos de Zhao disfrutan escribir y recitar poemas como este para expresar sus sentimientos.",
  ui_story_31880401_135_dialog_content = "No es raro verlos también en nuestras novelas.",
  ui_story_31880401_136_option_content = "¡Realmente interesante!",
  ui_story_31880401_137_dialog_content = "No creo haber leído nunca una novela tan imaginativa...",
  ui_story_31880401_138_dialog_content = "Siento que conozco a estos personajes en la vida real, pero parecen mucho más sofisticados en la historia.",
  ui_story_31880401_139_dialog_content = "Tú tenías razón, ¡esta novela es realmente interesante!",
  ui_story_31880401_140_dialog_content = "Parece que compartir esta novela contigo fue la decisión correcta después de todo.",
  ui_story_31880401_141_dialog_content = "¡El autor también trabaja muy rápido!",
  ui_story_31880401_142_dialog_content = "No han estado en Astra por mucho tiempo, ¡pero su historia ya se está publicando en toda nuestra tierra!",
  ui_story_31880401_143_dialog_content = "Hmph, parece otra novela barata para mí.",
  ui_story_31880401_144_dialog_content = "Resulta que soy un médico famoso y muy respetado que ayuda a los heridos y a los que sufren.",
  ui_story_31880401_145_dialog_content = "Pero esta historia me hace parecer un gato quejumbroso y perezoso.",
  ui_story_31880401_146_dialog_content = "¡Vaya tontería!",
  ui_story_31880401_147_dialog_content = "Oh, no lo veas de esa manera.",
  ui_story_31880401_148_dialog_content = "Al viajar por el mundo como lo hacemos, tener otra identidad es como tener otra capa de protección.",
  ui_story_31880401_149_dialog_content = "Creo que estas novelas están bastante bien escritas.",
  ui_story_31880401_150_dialog_content = "¿Tienes alguna otra identidad, Tianxian?",
  ui_story_31880401_151_dialog_content = "Ahora, ¿por qué preguntarías algo así? Los secretos no están hechos para ser compartidos, ¡ya sabes!",
  ui_story_31880401_152_dialog_content = "Espera, regresa...",
  ui_story_31880401_153_dialog_content = "Mi investigación está completa, Su Alteza.",
  ui_story_31880401_154_dialog_content = "La persona que publicó estas novelas es un hombre del Desierto de Rediesel llamado Jomu.",
  ui_story_31880401_155_dialog_content = "El autor tampoco parece ser de Zhao.",
  ui_story_31880401_156_dialog_content = "Esta persona Jomu parece estar planeando un viaje a Zhao para avanzar en sus intereses comerciales.",
  ui_story_31880401_157_dialog_content = "¿Necesitas que me deshaga de él?",
  ui_story_31880401_158_dialog_content = "¿Oh? Honestamente pensé que estas novelas fueron escritas por uno de nuestros compatriotas.",
  ui_story_31880401_159_dialog_content = "No tenía idea de que alguien en Astra estuviera tan versado en el estilo literario de Zhao!",
  ui_story_31880401_160_dialog_content = "Los libros gratuitos que trajiste de Zhou se han difundido ampliamente aquí. Creo que esto puede tener algo que ver con ello.",
  ui_story_31880401_161_dialog_content = "Parece que no hay escasez de talento en Astra entonces.",
  ui_story_31880401_162_dialog_content = "Y Jomu...?",
  ui_story_31880401_163_dialog_content = "Lo ha hecho bien, así que deberíamos apoyar sus esfuerzos.",
  ui_story_31880401_164_dialog_content = "Como enviado a Astra, este es exactamente el tipo de intercambio cultural que deseo promover.",
  ui_story_31880401_165_dialog_content = "Aunque la historia en estas novelas ha sido muy exagerada, eso no debería restarles valor.",
  ui_story_31880401_166_dialog_content = "La expresión de diferentes puntos de vista e ideologías...",
  ui_story_31880401_167_dialog_content = "Esta es parte de la prosperidad cultural que busco.",
  ui_story_31880401_168_dialog_content = "No solo eso...",
  ui_story_31880401_169_dialog_content = "\"Piel blanca como el hielo y rasgos finos como el jade tallado. Sus mejillas rosadas y labios rojos brillantes llenan este mundo de color y belleza.\"",
  ui_story_31880401_170_dialog_content = "\"Camina suavemente, tan ligera y elegante como una brisa entre las ramas de un sauce. Sus ojos evocan la ternura de los pétalos de flores cayendo delicadamente sobre un estanque de agua.\"",
  ui_story_31880401_171_dialog_content = "Por tonto que suene, todavía me gustan bastante estas líneas.",
  ui_story_31880401_172_dialog_content = "¡Jejeje!",
  ui_story_31880601_1_dialog_content = "El sonido de las olas susurrando en la noche suave y el parpadeo de las sombras a la luz de las velas...",
  ui_story_31880601_2_dialog_content = "Esta noche es hermosa.",
  ui_story_31880601_3_dialog_content = "Está.",
  ui_story_31880601_4_dialog_content = "Desde que dejé mi tierra natal por el Reino de Ji... he tenido pocas oportunidades para momentos de ocio como este.",
  ui_story_31880601_5_dialog_content = "Muchas gracias por invitarme a admirar la luna desde la playa.",
  ui_story_31880601_6_dialog_content = "Tu amable oferta me ha traído mucha alegría hoy.",
  ui_story_31880601_7_dialog_content = "¡No tienes que ser tan educado! También me lo estoy pasando bien...",
  ui_story_31880601_8_dialog_content = "Jejeje, parece que la contemplación de la luna de hoy fue un éxito rotundo para ambos.",
  ui_story_31880601_9_dialog_content = "Permíteme hacer un brindis por ti, amigo mío...",
  ui_story_31880601_10_dialog_content = "Ahh, el sonido de las olas es realmente reconfortante... Realmente me hace recordar un cierto recuerdo de mi pasado.",
  ui_story_31880601_11_dialog_content = "¿Una memoria en particular?",
  ui_story_31880601_12_dialog_content = "Sí. En ese momento, acababa de llegar al Reino de Ji y pasé mucho tiempo cerca del puerto.",
  ui_story_31880601_13_dialog_content = "Mi tierra natal, el Reino de Ye, es conocida por su experta artesanía, así como por su profundo conocimiento de la maquinaria...",
  ui_story_31880601_14_dialog_content = "Pero nunca había encontrado una tierra tan próspera de comercio y competencia. Realmente era un espectáculo digno de ver.",
  ui_story_31880601_15_dialog_content = "Fue una experiencia reveladora para alguien que acababa de llegar... En aquel entonces, a menudo miraba a lo lejos, perdido en mis propios pensamientos.",
  ui_story_31880601_16_dialog_content = "Allá en el horizonte, donde el cielo infinito se encuentra con el inmenso mar, innumerables barcos cargados de todo tipo de maravillas navegaban de un lado a otro...",
  ui_story_31880601_17_dialog_content = "Ajá...",
  ui_story_31880601_18_dialog_content = "¿Pasa algo? ¿O se está haciendo demasiado tarde para ti?",
  ui_story_31880601_19_option_content = "¿Eh? No... Por favor, continúa...",
  ui_story_31880601_20_option_content = "Solo estoy... un poco cansado...",
  ui_story_31880601_21_dialog_content = "Jeje, siéntete libre de cerrar los ojos y descansar un rato.",
  ui_story_31880601_22_dialog_content = "Aquí mismo, junto a mí...",
  ui_story_31880601_23_dialog_content = "...",
  ui_story_31880601_24_dialog_content = "... ¿Eh? ¿Dónde estoy? ¿Qué lugar es este?",
  ui_story_31880601_25_dialog_content = "Perdón, pero ¿estás bien?",
  ui_story_31880601_26_dialog_content = "D... Dantang?",
  ui_story_31880601_27_dialog_content = "¿Mmm? No creo que nos hayamos conocido antes. ¿Cómo sabe mi nombre, señor?",
  ui_story_31880601_28_dialog_content = "¿Podría ser que... ya me haya vuelto conocido?",
  ui_story_31880601_29_dialog_content = "Uh, ¿cómo debería explicar esto...? Estoy bastante seguro de que estoy soñando en este momento.",
  ui_story_31880601_30_dialog_content = "Jeje, sería bastante interesante si todo esto fuera solo un sueño.",
  ui_story_31880601_31_dialog_content = "Dime, ¿qué piensa un soñador como tú de este lugar?",
  ui_story_31880601_32_dialog_content = "Esta es tu primera vez en el puerto del Reino Ji, ¿verdad?",
  ui_story_31880601_33_dialog_content = "Mi primera vez en un sueño.",
  ui_story_31880601_34_dialog_content = "Entonces parece que necesitas un guía.",
  ui_story_31880601_35_dialog_content = "La verdad es que tampoco llevo mucho tiempo en esta ciudad.",
  ui_story_31880601_36_dialog_content = "Pero estoy bastante familiarizado con esta parte de la ciudad, ya que suelo venir aquí.",
  ui_story_31880601_37_dialog_content = "Eres más que bienvenido a unirte a mí, ¿si te gustaría?",
  ui_story_31880601_38_dialog_content = "En unos minutos, deberíamos poder ver muchos barcos grandes.",
  ui_story_31880601_39_dialog_content = "¿Barcos grandes?",
  ui_story_31880601_40_dialog_content = "Sí, enormes que son tan grandes como... ¡Oh mira, están aquí!",
  ui_story_31880601_41_dialog_content = "Tan grandes como casas, y sus enormes velas se hinchan como nubes en el cielo... Es realmente impresionante.",
  ui_story_31880601_42_dialog_content = "Oro para que algún día pueda abordar uno de esos barcos.",
  ui_story_31880601_43_dialog_content = "¿A dónde irías?",
  ui_story_31880601_44_dialog_content = "¿A dónde iría? Ahora que lo mencionas... Nunca lo he pensado mucho.",
  ui_story_31880601_45_dialog_content = "Los guardias dicen que estos barcos desafían olas traicioneras y tormentas aullantes para comerciar con tierras lejanas.",
  ui_story_31880601_46_dialog_content = "La valiente gente a bordo de estos barcos intercambia bienes por oro y viceversa.",
  ui_story_31880601_47_dialog_content = "Viajando constantemente en todas direcciones sin un momento de descanso... Nadie puede comprender qué les impulsa a hacerlo.",
  ui_story_31880601_48_dialog_content = "Pero aún así, les tengo envidia a todos.",
  ui_story_31880601_49_dialog_content = "No les envidiaría demasiado. Los viajes largos como ese pueden ser realmente peligrosos.",
  ui_story_31880601_50_dialog_content = "La gente aquí también estaría de acuerdo. Los guardias, los trabajadores del muelle y todos los demás.",
  ui_story_31880601_51_dialog_content = "Con cada oleada de partidas, siempre hay barcos que nunca regresan.",
  ui_story_31880601_52_dialog_content = "Tal vez se perdieron en el mar o fueron atacados por malvados espíritus oceánicos.",
  ui_story_31880601_53_dialog_content = "Incluso hay historias de hombres que se enamoran de las hijas del dios del mar, se casan con ellas y pierden toda esperanza de regresar a tierra.",
  ui_story_31880601_54_dialog_content = "Siempre que un barco se embarca en otro viaje, se habla de destino, peligro y presagios indescifrables...",
  ui_story_31880601_55_dialog_content = "Pero a pesar de todo, aún deseo viajar a bordo de uno de esos enormes barcos.",
  ui_story_31880601_56_dialog_content = "A pesar de que sabes que es peligroso, ¿por qué querrías hacer eso?",
  ui_story_31880601_57_dialog_content = "Porque además de su carga, estos barcos también llevan las esperanzas y sueños de muchas personas...",
  ui_story_31880601_58_dialog_content = "¡Y deseo ver por mí mismo los lugares en los que estas esperanzas y sueños se hacen realidad!",
  ui_story_31880601_59_dialog_content = "Al hacerlo, podría convertirme en alguien capaz de realizar los deseos de la gente...",
  ui_story_31880601_60_dialog_content = "Ves... ¿Cómo debería decirlo...?",
  ui_story_31880601_61_dialog_content = "... ¡No importa! Sonaría como una niña pequeña soñadora...",
  ui_story_31880601_62_dialog_content = "¡Jajaja, no te preocupes por eso! Estoy seguro de que podrás expresarte claramente a medida que vayas creciendo.",
  ui_story_31880601_63_dialog_content = "No hay nada de malo en tener un sueño o hablar de él, en todo caso.",
  ui_story_31880601_64_dialog_content = "¡Estoy de acuerdo! Entonces, cuando sea mayor, ¡definitivamente subiré a uno de esos barcos sin falta!",
  ui_story_31880601_65_dialog_content = "Veré por mí mismo lo que hay más allá y debajo del mar. ¡Y cuando llegue ese día, sabré exactamente cómo describir los sentimientos en mi corazón!",
  ui_story_31880601_66_dialog_content = "Entonces te estaré esperando al otro lado del mar.",
  ui_story_31880601_67_dialog_content = "¿Lo prometes?",
  ui_story_31880601_68_dialog_content = "Lo prometo.",
  ui_story_31880601_69_dialog_content = "... ¿Lo prometes...?",
  ui_story_31880601_70_dialog_content = "¿Lo hice...?",
  ui_story_31880601_71_dialog_content = "Ah, estás despierto. Pero no dormiste mucho tiempo.",
  ui_story_31880601_72_dialog_content = "¿Soñaste con algo?",
  ui_story_31880601_73_dialog_content = "Dantang...?",
  ui_story_31880601_74_dialog_content = "Mmm... No lo recuerdo muy claramente, pero definitivamente acabo de tener un sueño.",
  ui_story_31880601_75_dialog_content = "¿En serio? También estabas hablando en sueños, murmurando sobre barcos, promesas y cosas así.",
  ui_story_31880601_76_dialog_content = "May ¿Pregunto qué estabas soñando?",
  ui_story_31880601_77_dialog_content = "Es un poco difícil de explicar... De alguna manera, siento que sucedió hace mucho tiempo...",
  ui_story_31880601_78_dialog_content = "Jeje, realmente eres una persona interesante.",
  ui_story_31880601_79_dialog_content = "Trascendiendo el tiempo a través de los sueños... La idea definitivamente inspira pensamientos.",
  ui_story_31880601_80_dialog_content = "Jeje, te prometo que no intento sonar confuso ni nada. Ponerlo en palabras realmente es un poco difícil...",
  ui_story_31880601_81_dialog_content = "Debido a nuestras habilidades psíquicas, entrar e interpretar sueños es bastante fácil...",
  ui_story_31880601_82_dialog_content = "También he utilizado una técnica de sueños similar para ver lo que hay en los corazones de otras personas.",
  ui_story_31880601_83_dialog_content = "Me ayuda a resolver muchos problemas en el mundo real que, de lo contrario, no tendría forma de solucionar.",
  ui_story_31880601_84_dialog_content = "Por eso mis propios sueños suelen ser una combinación subconsciente de información...",
  ui_story_31880601_85_dialog_content = "Es como si mi cerebro trabajara horas extra mientras duermo, uniendo pedacitos de conocimiento que adquiero durante el día...",
  ui_story_31880601_86_dialog_content = "No—",
  ui_story_31880601_87_dialog_content = "¡Vaya! Lo siento, ¿no dije algo raro hace un momento, verdad...?",
  ui_story_31880601_88_dialog_content = "¡De ninguna manera! Después de todo, estamos hablando de sueños.",
  ui_story_31880601_89_dialog_content = "Recordando, soñaba bastante a menudo durante mis años de formación en el Reino Ji.",
  ui_story_31880601_90_dialog_content = "A veces incluso soñaba con montar en un enorme barco mientras zarpa para otro viaje...",
  ui_story_31880601_91_dialog_content = "¿Todavía sueñas con salir al mar?",
  ui_story_31880601_92_dialog_content = "Absolutamente, aunque mis sueños ya no son tan misteriosos como antes.",
  ui_story_31880601_93_dialog_content = "Después de todo, incluso he montado a bordo de tu Colossus ahora.",
  ui_story_31880601_94_dialog_content = "Ahora que lo mencionas... Si nada de esto hubiera pasado, ¿todavía querrías salir al mar?",
  ui_story_31880601_95_dialog_content = "No se puede negar que embarcarse en un viaje por el océano es como poner tu vida en manos del destino.",
  ui_story_31880601_96_dialog_content = "Pero al elegir salir al mar, ¿no es lo mismo que tomar el destino en nuestras propias manos también?",
  ui_story_31880601_97_dialog_content = "Pero aún podrías terminar en el vientre de un pez gigante.",
  ui_story_31880601_98_dialog_content = "Desde el momento en que nací, supuestamente mi destino estaba escrito en piedra, y la gente del Reino Ye me consideró un alma con mala suerte.",
  ui_story_31880601_99_dialog_content = "Pero en mis viajes, he aprendido que el destino no es tan inmutable como creemos.",
  ui_story_31880601_100_dialog_content = "Es por eso que creo que nosotros, como personas, tenemos el poder de luchar contra lo desconocido e incluso contra los mismos cielos.",
  ui_story_31880601_101_dialog_content = "¿Y tú? ¿Qué harías?",
  ui_story_31880601_102_dialog_content = "Si te enfrentaras a una oportunidad como esta, ¿también elegirías zarpar?",
  ui_story_31880601_103_option_content = "¡Saldría al mar!",
  ui_story_31880601_104_dialog_content = "Como era de esperar, tú y yo pensamos lo mismo.",
  ui_story_31880601_105_option_content = "¡Tengo mi propio camino por recorrer!",
  ui_story_31880601_106_dialog_content = "Tienes toda la razón. Después de todo, tu destino está en tus propias manos.",
  ui_story_31880601_107_dialog_content = "No es necesario seguir los pasos de otros ni hacer lo que ya han hecho.",
  ui_story_31880601_108_dialog_content = "Solo necesitas mantener tu propio destino a la vista y tomar un control firme de él.",
  ui_story_31880601_109_dialog_content = "De esa manera, ya sea en el mar o ante cambios inesperados, nunca perderás el rumbo.",
  ui_story_31880601_110_dialog_content = "Y si te llegas a perder, lo único que necesitas hacer es mirar hacia atrás.",
  ui_story_31880601_111_dialog_content = "Siempre habrá alguien esperándote.",
  ui_story_31880601_112_dialog_content = "Debí saberlo... La respuesta que encontraste después de crecer...",
  ui_story_31880601_113_dialog_content = "¡Es mucho más increíble de lo que podría haber imaginado!",
  ui_story_31880601_114_dialog_content = "¿Mmm? No entiendo...",
  ui_story_31880601_115_dialog_content = "¡No es nada! ¡Perdón por interrumpir!",
  ui_story_31880601_116_dialog_content = "Ahora, ¿dónde estábamos...? Ah, sí—¡siempre estaré esperando detrás de ti también, Dantang!",
  ui_story_31880601_117_dialog_content = "PlayerName...",
  ui_story_31880601_118_dialog_content = "Lo digo en serio... Así que sigamos hablando... Yo-yo prometo que... no estoy tan cansado...",
  ui_story_31880601_119_dialog_content = "¿Oh? Parece que nos hemos quedado despiertos un poco tarde. Tú también necesitas descansar.",
  ui_story_31880601_120_dialog_content = "La luna se ha ocultado detrás de un velo de nubes oscuras, así que terminemos la observación de esta noche por ahora.",
  ui_story_31880601_121_dialog_content = "Permíteme acompañarte de regreso a tu habitación.",
  ui_story_31880601_122_dialog_content = "Por favor, descansa mucho. Habrá muchos sueños por realizar para las dos tierras en el futuro..."
}
